import React, { useState } from 'react';

interface Stock {
    symbol: string;
    name: string;
    price: number;
    change: number;
    isFavorite: boolean;
}

const StockTable: React.FC<{ stocks: Stock[] }> = ({ stocks: initialStocks }) => {
    const [stocks, setStocks] = useState(initialStocks);

    const addToFavorites = async (symbol: string) => {
        try {
            await fetch(`http://localhost:8082/api/stocks/favorites/${symbol}`, {
                method: 'POST',
            });
            // Update local state to reflect the change
            const updatedStocks = stocks.map(s => 
                s.symbol === symbol ? { ...s, isFavorite: true } : s
            );
            setStocks(updatedStocks);
        } catch (error) {
            console.error('Error adding to favorites:', error);
        }
    };

    return (
        <table>
            <thead>
                <tr>
                    <th>Symbol</th>
                    <th>Name</th>
                    <th>Price</th>
                    <th>Change</th>
                    <th>Actions</th>
                </tr>
            </thead>
            <tbody>
                {stocks.map(stock => (
                    <tr key={stock.symbol}>
                        <td>{stock.symbol}</td>
                        <td>{stock.name}</td>
                        <td>${stock.price}</td>
                        <td>{stock.change}%</td>
                        <td>
                            <button onClick={() => addToFavorites(stock.symbol)}>
                                {stock.isFavorite ? '★' : '☆'}
                            </button>
                        </td>
                    </tr>
                ))}
            </tbody>
        </table>
    );
};

export default StockTable;
